import{_ as t,a as o,o as a,a6 as n}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse(`{"title":"Admin Authentication","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-authenticated-request","title":"Authenticated Request","description":"Every Admin REST call carries the admin Bearer token. This example reads the authenticated admin's own profile to confirm the token works.","query":"curl -X GET \\"https://your-domain.com/api/admin/get\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","variables":"{}\\n","response":"[\\n  {\\n    \\"id\\": \\"4\\",\\n    \\"name\\": \\"Admin User\\",\\n    \\"email\\": \\"admin@example.com\\",\\n    \\"image\\": null,\\n    \\"status\\": \\"1\\",\\n    \\"roleId\\": 1,\\n    \\"roleName\\": \\"Administrator\\",\\n    \\"success\\": true,\\n    \\"message\\": null\\n  }\\n]\\n","commonErrors":[{"error":"Unauthenticated","cause":"Missing, malformed, expired, or revoked Bearer token","solution":"Send a valid Bearer token from an active Integration token on the Authorization header"},{"error":"Forbidden","cause":"The token is valid but its permission scope does not cover the action","solution":"Use a token whose permission mode grants the required ACL key, and whose owning admin's role also grants it"}]}]},"headers":[],"relativePath":"api/rest-api/admin/authentication.md","filePath":"api/rest-api/admin/authentication.md","lastUpdated":1787725411000}`),i={name:"api/rest-api/admin/authentication.md"};function s(r,e,d,l,h,c){return a(),o("div",null,e[0]||(e[0]=[n(`<h1 id="admin-authentication" tabindex="-1">Admin Authentication <a class="header-anchor" href="#admin-authentication" aria-label="Permalink to &quot;Admin Authentication&quot;">​</a></h1><p>The Bagisto Admin REST API authenticates every request with a pre-issued <strong>Integration token</strong>. There is no login call — you generate a token once in the admin panel and send it on every request.</p><h2 id="how-to-authenticate" tabindex="-1">How to authenticate <a class="header-anchor" href="#how-to-authenticate" aria-label="Permalink to &quot;How to authenticate&quot;">​</a></h2><ol><li>In the admin panel, open the <strong>Integration</strong> menu (<code>Admin → Integration</code>) and generate a token.</li><li>Copy the token the moment it is shown — it is displayed <strong>once</strong>.</li><li>Send it on every Admin API request as a Bearer token:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization: Bearer &lt;id&gt;|&lt;token&gt;</span></span></code></pre></div><p>That single header is all that is required. The <code>/api/admin/*</code> routes do <strong>not</strong> use the storefront key — only the Bearer token above.</p><h2 id="about-the-token" tabindex="-1">About the token <a class="header-anchor" href="#about-the-token" aria-label="Permalink to &quot;About the token&quot;">​</a></h2><ul><li>The token belongs to a specific admin user and carries that admin&#39;s permissions. A request can never do more than the owning admin is allowed to do.</li><li>The plaintext format is <code>&lt;id&gt;|&lt;random&gt;</code>. Send it verbatim.</li><li>A token can be locked down with scoped <strong>permissions</strong>, an <strong>IP allowlist</strong>, an <strong>expiry date</strong>, and <strong>rate limits</strong> — see <a href="#token-security">Token security</a> below.</li><li>Revoke or regenerate a token at any time from the same <strong>Integration</strong> menu. A revoked token stops working immediately.</li></ul><h2 id="token-security" tabindex="-1">Token security <a class="header-anchor" href="#token-security" aria-label="Permalink to &quot;Token security&quot;">​</a></h2><p>Each Integration token can be locked down at generation time in the <strong>Integration</strong> menu. Four independent controls scope what a token can do:</p><h3 id="permissions-acl" tabindex="-1">Permissions (ACL) <a class="header-anchor" href="#permissions-acl" aria-label="Permalink to &quot;Permissions (ACL)&quot;">​</a></h3><p>A token is tied to one admin and <strong>inherits that admin&#39;s role permissions</strong> — it can never do more than its owner. When generating the token you choose a permission mode:</p><ul><li><strong>All</strong> — every action the owner&#39;s role allows.</li><li><strong>Custom</strong> — a specific subset of permissions you select, frozen onto the token.</li><li><strong>Same as web</strong> — always mirrors the owner&#39;s current role, so the token automatically follows any later changes to that role.</li></ul><p>A request for an action the token isn&#39;t permitted to perform returns HTTP <code>403</code> with a problem-details body:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/errors/403&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;title&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Forbidden&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">403</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;detail&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;You do not have permission to view this sales resource.&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="ip-allowlist" tabindex="-1">IP allowlist <a class="header-anchor" href="#ip-allowlist" aria-label="Permalink to &quot;IP allowlist&quot;">​</a></h3><p>Optionally restrict a token to specific client IPs. Individual <strong>IPv4</strong> and <strong>IPv6</strong> addresses and <strong>CIDR ranges</strong> are all supported. Leave the allowlist empty to allow any IP. A request from an address that isn&#39;t on the list is rejected as <strong>401 Unauthenticated</strong>. (<code>127.0.0.1</code> is always allowed, for local development.)</p><h3 id="expiry" tabindex="-1">Expiry <a class="header-anchor" href="#expiry" aria-label="Permalink to &quot;Expiry&quot;">​</a></h3><p>A token can have an <strong>expiry date</strong> (default: one year after generation) or be set to <strong>never expire</strong>. After the expiry date the token stops working (<strong>401</strong>).</p><h3 id="rate-limits" tabindex="-1">Rate limits <a class="header-anchor" href="#rate-limits" aria-label="Permalink to &quot;Rate limits&quot;">​</a></h3><p>Each token carries two independent caps, both set when the token is generated:</p><table tabindex="0"><thead><tr><th>Bucket</th><th>Default</th></tr></thead><tbody><tr><td>Per minute</td><td>60 requests</td></tr><tr><td>Per day</td><td>10,000 requests</td></tr></tbody></table><p>Exceeding either returns HTTP <code>429</code> with <code>{&quot;message&quot;: &quot;Too Many Attempts.&quot;, &quot;error&quot;: &quot;rate_limit_exceeded&quot;}</code> and these headers:</p><table tabindex="0"><thead><tr><th>Header</th><th>Meaning</th></tr></thead><tbody><tr><td><code>Retry-After</code></td><td>Seconds until the bucket refills</td></tr><tr><td><code>X-RateLimit-Limit</code></td><td>The cap that was hit</td></tr><tr><td><code>X-RateLimit-Remaining</code></td><td>Requests left, <code>0</code> on a 429</td></tr><tr><td><code>X-RateLimit-Reset</code></td><td>Unix timestamp when the window resets</td></tr></tbody></table><p>Three details worth knowing:</p><ul><li><strong>The two caps are separate buckets.</strong> Hitting the per-minute cap does not consume the daily allowance, and the <code>Retry-After</code> you get back tells you which one you hit — roughly a minute versus the remainder of the day.</li><li><strong>The cap is per token, not per admin or per IP.</strong> Two tokens owned by the same admin have independent allowances.</li><li><strong>REST and GraphQL share one bucket.</strong> <code>/api/admin/graphql</code> draws on the same per-token allowance as the REST routes, so a client using both must budget across the two.</li></ul><p>Choose <strong>Unlimited</strong> for either bucket when generating or editing the token to remove that cap; set both to Unlimited for an unthrottled token.</p><h2 id="token-lifecycle" tabindex="-1">Token lifecycle <a class="header-anchor" href="#token-lifecycle" aria-label="Permalink to &quot;Token lifecycle&quot;">​</a></h2><ul><li><strong>One active token per admin.</strong> Each admin user holds a single active (or draft) token at a time. To issue a new one, revoke or regenerate the existing token first — the generate form only offers admins who don&#39;t already have one.</li><li><strong>States.</strong> A token moves through <strong>draft</strong> (created but not yet generated — no secret), <strong>active</strong> (generated and usable), <strong>revoked</strong> (manually killed — stops working immediately, kept for audit), and <strong>regenerated</strong> (superseded by a newer token — the old row is retired but kept for audit).</li><li><strong>Regenerate.</strong> Issues a fresh secret on a new token row and retires the old one; the new plaintext is shown <strong>once</strong>. Use it when a token may be compromised, without losing the audit trail.</li><li><strong>Revoke.</strong> Kills the token immediately — from the Integration menu, or the one-click link in the lifecycle email.</li><li><strong>Email notifications.</strong> The owning admin is emailed on generate, regenerate, and revoke. Generate and regenerate emails carry a <strong>signed, 7-day, login-free revoke link</strong> so the owner can kill a token from their inbox. The plaintext token is <strong>never</strong> included in any email.</li></ul><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>HTTP</th><th>Body</th></tr></thead><tbody><tr><td>Missing / malformed / expired / revoked token, or client IP not on the token&#39;s allowlist</td><td><code>401</code></td><td><code>{&quot;message&quot;: &quot;Unauthenticated.&quot;, &quot;error&quot;: &quot;unauthenticated&quot;}</code></td></tr><tr><td>Token valid but lacks permission for the action</td><td><code>403</code></td><td><code>{&quot;type&quot;: &quot;/errors/403&quot;, &quot;title&quot;: &quot;Forbidden&quot;, &quot;status&quot;: 403, &quot;detail&quot;: &quot;...&quot;}</code></td></tr><tr><td>Resource does not exist</td><td><code>404</code></td><td><code>{&quot;type&quot;: &quot;/errors/404&quot;, &quot;title&quot;: &quot;Not Found&quot;, &quot;status&quot;: 404, &quot;detail&quot;: &quot;...&quot;}</code></td></tr><tr><td>Per-minute or per-day rate limit exceeded</td><td><code>429</code></td><td><code>{&quot;message&quot;: &quot;Too Many Attempts.&quot;, &quot;error&quot;: &quot;rate_limit_exceeded&quot;}</code></td></tr></tbody></table><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><p>Use the interactive example on the right to see an authenticated request in cURL, Node.js, React, and PHP.</p>`,33)]))}const g=t(i,[["render",s]]);export{p as __pageData,g as default};
